const refreshCashStatementPeriod = `-- name: RefreshCashStatementPeriod :exec
UPDATE cash_statements s
SET period_from = LEAST(s.period_from, l.first_date), period_to = GREATEST(s.period_to, l.last_date)
FROM (
    SELECT MIN(line_date)::date AS first_date, MAX(line_date)::date AS last_date
    FROM cash_statement_lines
    WHERE organization_id = $1 AND statement_id = $2
) l
WHERE s.organization_id = $1 AND s.id = $2 AND l.first_date IS NOT NULL
`

type RefreshCashStatementPeriodParams struct {
	OrganizationID int64 `json:"organization_id"`
	StatementID    int64 `json:"statement_id"`
}

// Widens the statement period to cover its lines.
func (q *Queries) RefreshCashStatementPeriod(ctx context.Context, arg RefreshCashStatementPeriodParams) error {
	_, err := q.db.Exec(ctx, refreshCashStatementPeriod, arg.OrganizationID, arg.StatementID)
	return err
}

